head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf15000";
scwin.dmenus = undefined;
scwin.srchCond1 = null;
scwin.srchCond2 = null;
scwin.srchCond3 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_datefmt_cal_procsReqDd
 * @description 초기화 — datefmt cal procs Req Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_procsReqDd = function () { $c.date.checkCalendarFormat("cal_procsReqDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_genmeetHldDd
 * @description 초기화 — datefmt cal genmeet Hld Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_genmeetHldDd = function () { $c.date.checkCalendarFormat("cal_genmeetHldDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_rsnOccrDd
 * @description 초기화 — datefmt cal rsn Occr Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_rsnOccrDd = function () { $c.date.checkCalendarFormat("cal_rsnOccrDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf15000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.srchCond1 = '' + dma_searchCondition.get("srch_cond_1") + '';
        scwin.srchCond2 = '' + dma_searchCondition.get("srch_cond_2") + '';
        scwin.srchCond3 = '' + dma_searchCondition.get("srch_cond_3") + '';
        scwin.init_recvParam();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_genmeetHldDd();
        scwin.init_datefmt_cal_rsnOccrDd();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf15000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15000.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15000.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name ipt_srchCond0_onclick
 * @description ipt_srchCond0 클릭 이벤트
