 * @hidden N
 */
scwin.ipt_srchCond3_onclick = async function(e){
    try {
        await scwin.searchBndList(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15000.ipt_srchCond3_onclick' }); }
};

/**
 * @method
 * @name objBndList_oncellclick
 * @description objBndList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.objBndList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "check") { await scwin.setChgBasIsuNm(); return; }
        /* TODO Stage2: 행 동작 미정의: scwin.detail (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.detail'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'objBndList.oncellclick' });
    }
};

/**
 * @method
 * @name slc_bdchrgTpCd_onchange
 * @description slc_bdchrgTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_bdchrgTpCd_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.getBdchrgInfo(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15000.slc_bdchrgTpCd_onchange' }); }
};

/**
 * @method
 * @name btn_fileBrowse_onclick
 * @description btn_fileBrowse 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileBrowse_onclick = function(e){
    try {
        $c.util.onUploadClick($c.util.getComponent('mpd_files'))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15000.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15000.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name btn_save_onclick
 * @description btn_save 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15000.btn_save_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchBndList
 * @description search Bnd List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchBndList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchBndList",
        method: "post",
        action: "/company/company.do?method=searchBndListByCoNmChg",
        ref: "dma_searchBndListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/company/company.do?method=saveCompanyName",
        ref: "dma_saveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_GetBdchrgInfo
 * @description Get Bdchrg Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetBdchrgInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_GetBdchrgInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_GetBdchrgInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value !== null ? fm.value : null); if (v === null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name searchBndList
 * @description search Bnd List 처리
 * @param {*} chkDiv chkDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchBndList = async function (chkDiv) {
    const fm = (document.SendForm || { elements: [] });
    if (chkDiv === '0') {
        const srchCond = (String($c.util.getComponent('ipt_srchCond0').getValue() || "") !== "");
        $c.util.getComponent("ipt_srchCond1").setValue(srchCond);
        $c.util.getComponent("ipt_srchCond2").setValue(srchCond);
        $c.util.getComponent("ipt_srchCond3").setValue(srchCond);
    } else {
        $c.util.getComponent("ipt_srchCond0").setValue(false);
    }
    if (((!$c.util.getComponent('ipt_srchCond1') || typeof $c.util.getComponent('ipt_srchCond1').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_srchCond1'), false) : ($c.util.getComponent('ipt_srchCond1').getValue() !== null && String($c.util.getComponent('ipt_srchCond1').getValue()) !== '')) === false) {
        $c.util.getComponent("ipt_srchCond1").setValue('0');
        $c.util.getComponent("ipt_srchCond1").setValue(true);
    } else {
        $c.util.getComponent("ipt_srchCond1").setValue('1');
    }
    if (((!$c.util.getComponent('ipt_srchCond2') || typeof $c.util.getComponent('ipt_srchCond2').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_srchCond2'), false) : ($c.util.getComponent('ipt_srchCond2').getValue() !== null && String($c.util.getComponent('ipt_srchCond2').getValue()) !== '')) === false) {
        $c.util.getComponent("ipt_srchCond2").setValue('0');
        $c.util.getComponent("ipt_srchCond2").setValue(true);
    } else {
        $c.util.getComponent("ipt_srchCond2").setValue('1');
    }
    if (((!$c.util.getComponent('ipt_srchCond3') || typeof $c.util.getComponent('ipt_srchCond3').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_srchCond3'), false) : ($c.util.getComponent('ipt_srchCond3').getValue() !== null && String($c.util.getComponent('ipt_srchCond3').getValue()) !== '')) === false) {
        $c.util.getComponent("ipt_srchCond3").setValue('0');
        $c.util.getComponent("ipt_srchCond3").setValue(true);
    } else {
        $c.util.getComponent("ipt_srchCond3").setValue('1');
    }
    fm.action = '/company/company.do?method=searchBndListByCoNmChg';
    await scwin.tx_fn_searchBndList();
};

/**
 * @method
 * @name chgAllIsuNm
 * @description chg All Isu Nm 처리
 * @returns {void}
 * @hidden N
 */
scwin.chgAllIsuNm = function () {
    let afchg_isu_nm = $c.util.getComponent('ipt_afchgIsuNm').getValue(); if (afchg_isu_nm === null) { afchg_isu_nm = ''; }
    let afchg_isu_eng_nm = $c.util.getComponent('ipt_afchgIsuEngNm').getValue(); if (afchg_isu_eng_nm === null) { afchg_isu_eng_nm = ''; }
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {const idx = r;
        $c.util.getComponent('dlt_result').setCellData(r, 'applIsuNm', afchg_isu_nm + ' ' + $c.util.getComponent('dlt_result').getCellData(r, 'unqIsuNm'));
        $c.util.getComponent('dlt_result').setCellData(r, 'applIsuEngNm', afchg_isu_eng_nm + ' ' + $c.util.getComponent('dlt_result').getCellData(r, 'unqIsuEngNm'));
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    const fm = (document.SendForm || { elements: [] });
    fm.action = '/company/company.do?method=saveCompanyName';
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    const _mktact_cd = $c.util.getComponent("dma_searchBndListReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchBndListReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_isurNm').getValue()) === 0) {
                await $c.win.alert("변경후 발행기관(한글)을 입력하십시오.");
                $c.util.getComponent("ipt_isurNm").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_isurEngNm').getValue()) === 0) {
                    await $c.win.alert("변경후 발행기관명(영문)을 입력하십시오.");
                    $c.util.getComponent("ipt_isurEngNm").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('cal_genmeetHldDd').getValue()) === 0) {
                        await $c.win.alert("주주(임시)총회일을 입력하십시오.");
                        $c.util.getComponent("cal_genmeetHldDd").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('cal_rsnOccrDd').getValue()) === 0) {
                            await $c.win.alert("변경등기일을 입력하십시오.");
                            $c.util.getComponent("cal_rsnOccrDd").focus();
                            return false;
                        } else {
                            if (!await scwin.CheckChgIsuNm(fm)) {
                                return false;
                            } else {
                                if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                                    return false;
                                } else {
                                    if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) === 0) {
                                        return false;
                                    } else {
                                        if (!await scwin.CheckReqInfo_Cellphone(fm)) {
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
};

/**
 * @method
 * @name CheckChgIsuNm
 * @description Check Chg Isu Nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckChgIsuNm = async function (fm) {
    let isNull = false;
    let checkNum = 0;
    $i = 0;
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {
        if ($c.util.getComponent('dlt_result').getRowCount() === 1) {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'applIsuNm')) === 0) {
                    await $c.win.alert("선택된 상호변경대상 종목의 변경후 한글종목명을 입력하십시오.");
                    ipt_applIsuNm.focus();
                    isNull = true;
                } else {
