                        ipt_applIsuEngNm.focus();
                        isNull = true;
                    }
                }
                checkNum = checkNum + 1;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'applIsuNm')) > 0) {
                    ipt_applIsuNm.setValue('');
                }
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData(0, 'applIsuEngNm')) > 0) {
                    ipt_applIsuEngNm.setValue('');
                }
            }
        } else {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'applIsuNm')) === 0) {
                    await $c.win.alert("선택된 상호변경대상 종목의 변경후 한글종목명을 입력하십시오.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    isNull = true;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'applIsuEngNm')) === 0) {
                        await $c.win.alert("선택된 상호변경대상 종목의 변경후 영문종목명을 입력하십시오.");
                        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                        isNull = true;
                    }
                }
                checkNum = checkNum + 1;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'applIsuNm')) > 0) {
                    $c.util.getComponent('dlt_result').setCellData($i, 'applIsuNm', (''));
                }
                if ($c.str.getByteLength($c.util.getComponent('dlt_result').getCellData($i, 'applIsuEngNm')) > 0) {
                    $c.util.getComponent('dlt_result').setCellData($i, 'applIsuEngNm', (''));
                }
            }
        }
        $i = $i + 1;
    }
    if (checkNum === 0) {
        await $c.win.alert("하나 이상의 종목을 선택하십시오.");
        ipt_checkAll.focus();
        return false;
    } else {
        if (!isNull) {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent("cal_procsReqDd").setValue("");
    $c.util.getComponent("ipt_isurNm").setValue("");
    $c.util.getComponent("ipt_isurEngNm").setValue("");
    $c.util.getComponent("cal_genmeetHldDd").setValue("");
    $c.util.getComponent("cal_rsnOccrDd").setValue("");
    afchg_isu_nm.setValue("");
    afchg_isu_eng_nm.setValue("");
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {const idx = r;
        $c.util.getComponent('dlt_result').setCellData(r, 'applIsuNm', '');
        $c.util.getComponent('dlt_result').setCellData(r, 'applIsuEngNm', '');
    }
};

/**
 * @method
 * @name selectAll_2
 * @description select All 2 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll_2 = function () {
    let checked = $("#ipt_checkAll").attr("checked");
    if (checked === "checked") {
        checked = true;
    } else {
        checked = false;
    }
    $.each($("#SendForm").find("input[name='check']"), function(i) {
            let subChecked = $(this).attr("checked");
            if (subChecked === "checked") {
                subChecked = true;
            } else {
                subChecked = false;
            }
            if (subChecked !== checked) {
                $(this).attr("checked", checked);
            }
    });
};

/**
 * @method
 * @name setChgBasIsuNm
 * @description set Chg Bas Isu Nm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setChgBasIsuNm = async function () {
    const fm = (document.SendForm || { elements: [] });
    let afchg_isu_nm = $c.util.getComponent('ipt_afchgIsuNm').getValue(); if (afchg_isu_nm === null) { afchg_isu_nm = ''; }
    let afchg_isu_eng_nm = $c.util.getComponent('ipt_afchgIsuEngNm').getValue(); if (afchg_isu_eng_nm === null) { afchg_isu_eng_nm = ''; }
    if (afchg_isu_nm === "") {
        await $c.win.alert("변경후 한글기준명을 입력하십시오.");
        ($c.util.getComponent('ipt_afchgIsuNm') && $c.util.getComponent('ipt_afchgIsuNm').setFocus ? $c.util.getComponent('ipt_afchgIsuNm').setFocus() : ($c.util.getComponent('ipt_afchgIsuNm') && $c.util.getComponent('ipt_afchgIsuNm').focus ? $c.util.getComponent('ipt_afchgIsuNm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_afchgIsuNm')));
        return;
    }
    if (afchg_isu_eng_nm === "") {
        await $c.win.alert("변경후 영문기준명을 입력하십시오.");
        ($c.util.getComponent('ipt_afchgIsuEngNm') && $c.util.getComponent('ipt_afchgIsuEngNm').setFocus ? $c.util.getComponent('ipt_afchgIsuEngNm').setFocus() : ($c.util.getComponent('ipt_afchgIsuEngNm') && $c.util.getComponent('ipt_afchgIsuEngNm').focus ? $c.util.getComponent('ipt_afchgIsuEngNm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_afchgIsuEngNm')));
        return;
    }
    $i = 0;
    for (let r = 0, n = $c.util.getComponent('dlt_result').getRowCount(); r < n; r++) {
        if ($c.util.getComponent('dlt_result').getRowCount() === 1) {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                ipt_applIsuNm.setValue(afchg_isu_nm + ' ' + $c.util.getComponent("dma_searchBndListReq").get("unqIsuNm"));
                ipt_applIsuEngNm.setValue(afchg_isu_eng_nm + ' ' + $c.util.getComponent("dma_searchBndListReq").get("unqIsuEngNm"));
            } else {
                ipt_applIsuNm.setValue("");
                ipt_applIsuEngNm.setValue("");
            }
        } else {
            if ((['true', 'Y', '1', 'on'].indexOf(String($c.util.getComponent('dlt_result').getCellData(r, 'check'))) >= 0)) {
                $c.util.getComponent('dlt_result').setCellData($i, 'applIsuNm', (afchg_isu_nm + ' ' + $c.util.getComponent('dlt_result').getCellData($i, 'unqIsuNm')));
                $c.util.getComponent('dlt_result').setCellData($i, 'applIsuEngNm', (afchg_isu_eng_nm + ' ' + $c.util.getComponent('dlt_result').getCellData($i, 'unqIsuEngNm')));
            } else {
                $c.util.getComponent('dlt_result').setCellData($i, 'applIsuNm', (""));
                $c.util.getComponent('dlt_result').setCellData($i, 'applIsuEngNm', (""));
            }
        }
        $i = $i + 1;
    }
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo !== null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

